package greeter

import "strings"

// Slug 把一段文本折成小写连字符 slug：去掉首尾空白，
// 连续的空白折成一个连字符。
func Slug(s string) string {
	return strings.ToLower(strings.Join(strings.Fields(s), "-"))
}

package greeter

import "testing"

func TestJoinSlug(t *testing.T) {
	cases := []struct {
		name string
		in   []string
		want string
	}{
		{"two parts", []string{"Hello World", "Big Day"}, "hello-world/big-day"},
		{"skip blank", []string{"a", "", "b"}, "a/b"},
		{"skip whitespace", []string{"a", "   ", "b"}, "a/b"},
		{"no parts", nil, ""},
	}
	for _, c := range cases {
		if got := JoinSlug(c.in...); got != c.want {
			t.Errorf("%s: JoinSlug(%q) = %q, want %q", c.name, c.in, got, c.want)
		}
	}
}

package greeter

import "strings"

// JoinSlug 把各段文本折成 slug 后用 "/" 串起来，
// 空串与纯空白段被跳过。
func JoinSlug(parts ...string) string {
	slugs := make([]string, 0, len(parts))
	for _, p := range parts {
		if s := Slug(p); s != "" {
			slugs = append(slugs, s)
		}
	}
	return strings.Join(slugs, "/")
}
